  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    super.dispose();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed) {
      _refresh();
    }
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: Duration(milliseconds: 400),
      vsync: this,
    );
  }

  void _initData() {
    setState(() {
      _filteredCurrenciesNotifier = ValueNotifier(const []);
      _currencyPageFuture = _loadPage(_request);
    });
  }

  /// Обновляет список свежим запросом первой страницы с `base: 'USD'`.
  void _refresh() {
    _request = const CurrencyPageRequest(base: _baseCurrency);

    setState(() {
      _currencyPageFuture = _loadPage(_request);
    });
  }

  Future<CurrencyPage> _loadPage(CurrencyPageRequest request) {
    final CurrencyRepository currencyRepository = context.read<CurrencyRepository>();

    return currencyRepository.fetchRates(request).then((CurrencyPage page) {
      _allCurrencies = page.items;
      _filteredCurrenciesNotifier.value = page.items;
      _hasMore = page.hasMore;

      if (request.page == 0) {
        _fadeController.forward(); // запускаем анимацию
      }

      currencyRepository.saveCurrencyList(page.items);

      return page;
    });
  }

  void _showMore() {
    final CurrencyPageRequest nextRequest = CurrencyPageRequest(
      base: _request.base,
      page: _request.page + 1,
      pageSize: _request.pageSize,
    );

    setState(() {
      _request = nextRequest;
      _currencyPageFuture = _loadPage(nextRequest);
    });
  }

  void _filterCurrencies(String query) {
    final String lowerQuery = query.toLowerCase();
    final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
      return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
    });

    _filteredCurrenciesNotifier.value = result.toList(growable: false);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: FutureBuilder<CurrencyPage>(
        future: _currencyPageFuture,
        builder: (BuildContext context, AsyncSnapshot<CurrencyPage> snapshot) {
          final CurrencyPage? page = snapshot.data;
          if (page == null) return const SizedBox.shrink();

          return FadeTransition(
            opacity: _fadeController.view,
            child: Column(
              children: [
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                  child: SearchView(onChanged: _filterCurrencies),
                ),
                Expanded(
                  child: ValueListenableBuilder<List<CurrencyModel>>(
                    valueListenable: _filteredCurrenciesNotifier,
                    builder: (BuildContext context, List<CurrencyModel> data, _) {
                      return ListView.builder(
                        itemCount: data.length,
                        itemBuilder: (BuildContext context, int index) {
                          final CurrencyModel currency = data[index];

                          return Padding(
                            key: ValueKey(currency.id),
                            padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
                            child: CurrencyCard(model: currency),
                          );
                        },
                        padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
                      );
                    },
                  ),
                ),
                if (_hasMore)
                  Padding(
                    padding: const EdgeInsets.fromLTRB(22, 8, 22, 24),
                    child: SizedBox(
                      width: double.infinity,
                      child: ElevatedButton(
                        onPressed: _showMore,
                        child: Text(context.loc.showMore),
                      ),
                    ),
                  ),
              ],
            ),
          );
        },
      ),
    );
  }
}

